function encodeDownlink(data) {
  const bytes = [];
  for (const key of Object.keys(data)) {
    switch (key) {
      case "setKeepAlive": { bytes.push(0x02); bytes.push(data.setKeepAlive); break; }
      case "setChildLock": { bytes.push(0x07); bytes.push(Number(data.setChildLock)); break; }
      case "setTargetTemperature": { bytes.push(0x0e); bytes.push(data.setTargetTemperature); break; }
      default: break;
    }
  }
  return bytes;
}
function consume(event) {
  const payloadNumber = encodeDownlink(event.payload);
  let payloadHex = "";
  payloadNumber.forEach(byte => { payloadHex += byte.toString(16).padStart(2, "0"); });
  emit("downlink", { payloadHex, port: 1, confirmed: true });
}
